import '@servicenow/sdk/global'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for AssignSubflowOutputs validation - invalid placement
 * Should fail: AssignSubflowOutputs can only be used within SubflowDefinition or Subflow
 */
export const assignSubflowOutputsInvalidPlacement = Flow(
    {
        $id: Now.ID['assign-subflow-outputs-invalid-placement'],
        name: 'AssignSubflowOutputs Invalid Placement Test',
        description: 'Test AssignSubflowOutputs validation in regular Flow (not SubflowDefinition)',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['assign-outputs-invalid-placement-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // This should fail validation: AssignSubflowOutputs in regular Flow
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-invalid-placement'],
                annotation: 'Invalid: used in regular Flow instead of SubflowDefinition',
            },
            (params as any).outputs, // This doesn't exist in Flow
            {
                result: 'value',
            }
        )
    }
)
